window.products.push({"id":189566,"name":"One Ounce Scales USA Digital Scale Test or Calibration Weight","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/616N2ZW5X-L._AC_SL1024_.jpg","description":"This is a one ounce chrome plated weight. It includes a certificate from the manufacturer stating its accuracy, and is safely packed in a foam lined ABS Storage case with screw-off top. It is suitable for calibrating or checking the accuracy of a consumer grade scale. The weight is made of steel that is chrome plated, and is adjusted by adding material to a cavity in the bottom of the weight and then sealing it with a pressed in tamper proof seal. It is stamped 1 OZ on the top.","images":["https://m.media-amazon.com/images/I/616N2ZW5X-L._AC_SL1024_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Scales USA","source_asin":"B01BPE7N2W","category_path":"Home & Kitchen"},"sku":"BM-189566","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01BPE7N2W","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01BPE7N2W","price_pending":true,"merchant_ready":false});
